create table if not exists public.competitor_snapshots(id bigint generated always as identity primary key,competitor_id uuid not null references public.competitors(id) on delete cascade,workspace_id uuid not null references public.workspaces(id) on delete cascade,metric_date date not null default current_date,metrics jsonb not null default '{}',created_at timestamptz not null default now(),unique(competitor_id,metric_date));create index if not exists competitor_snapshots_workspace_date_idx on public.competitor_snapshots(workspace_id,metric_date desc);alter table public.competitor_snapshots enable row level security;create policy "members view competitor snapshots" on public.competitor_snapshots for select to authenticated using(exists(select 1 from public.workspace_members wm where wm.workspace_id=competitor_snapshots.workspace_id and wm.user_id=(select auth.uid())));grant select on public.competitor_snapshots to authenticated;grant all on public.competitor_snapshots to service_role;